/** Job representation shared by the server and the worker. */

export const MAX_ATTEMPTS = 3;
/** Time for one processing step. */
export const STEP_MS = 100;
/** Delay before a failed attempt is retried. */
export const RETRY_DELAY_MS = 500;
export const TRANSIENT_ERROR = 'transient failure';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A row of the `jobs` table, as returned by SQLite. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  output: string | null;
  error: string | null;
  idempotency_key: string | null;
  next_run_at: number;
  created_at: string;
  updated_at: string;
}

/** The JSON shape returned by every endpoint that returns a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export function nowIso(): string {
  return new Date().toISOString();
}

