/** Validation of job submissions. Defaults are applied here, so idempotency compares the final payload. */

export interface FieldError {
  field: string;
  message: string;
}

export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

export const DEFAULT_STEPS = 5;
export const DEFAULT_FAIL_ATTEMPTS = 0;
export const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

export type ValidationResult = { ok: true; value: Submission } | { ok: false; fields: FieldError[] };

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function integerIn(value: unknown, min: number, max: number): boolean {
  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
}

export function validateSubmission(body: unknown): ValidationResult {
  if (!isPlainObject(body)) {
    return { ok: false, fields: [{ field: 'body', message: 'body must be a JSON object' }] };
  }
  const fields: FieldError[] = [];
  for (const key of Object.keys(body)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }

  let input = '';
  if (!Object.hasOwn(body, 'input')) {
    fields.push({ field: 'input', message: 'input is required' });
  } else if (typeof body.input !== 'string') {
    fields.push({ field: 'input', message: 'input must be a string' });
  } else if (body.input.length < 1 || body.input.length > 1000) {
    fields.push({ field: 'input', message: 'input must be 1 to 1000 characters' });
  } else if (body.input.trim() === '') {
    fields.push({ field: 'input', message: 'input must not be only whitespace' });
  } else {
    input = body.input;
  }

  let steps = DEFAULT_STEPS;
  if (Object.hasOwn(body, 'steps')) {
    if (integerIn(body.steps, 1, 20)) steps = body.steps as number;
    else fields.push({ field: 'steps', message: 'steps must be an integer from 1 to 20' });
  }

  let failAttempts = DEFAULT_FAIL_ATTEMPTS;
  if (Object.hasOwn(body, 'failAttempts')) {
    if (integerIn(body.failAttempts, 0, 5)) failAttempts = body.failAttempts as number;
    else fields.push({ field: 'failAttempts', message: 'failAttempts must be an integer from 0 to 5' });
  }

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input, steps, failAttempts } };
}

