import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import type { DatabaseSync } from 'node:sqlite';
import { inTransaction, openDatabase } from './db.ts';
import { nowIso, toJob, type Job, type JobRow } from './jobs.ts';
import { IDEMPOTENCY_KEY_PATTERN, validateSubmission, type FieldError, type Submission } from './validate.ts';

const MAX_BODY_BYTES = 64 * 1024;
const WORKER_STALE_MS = 3000;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function invalidRequest(res: ServerResponse, fields: FieldError[]): void {
  sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
}

/** Reads the request body as text. `tooLarge` is set when it exceeds the limit. */
function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

function isJsonContentType(header: string | undefined): boolean {
  if (!header) return false;
  return header.split(';')[0]!.trim().toLowerCase() === 'application/json';
}

function getJobRow(id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
}

function insertJob(sub: Submission, idempotencyKey: string | null): JobRow {
  const id = randomUUID();
  const now = nowIso();
  db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, idempotency_key, next_run_at, created_at, updated_at)
     VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
  ).run(id, sub.input, sub.steps, sub.failAttempts, idempotencyKey, now, now);
  return getJobRow(id)!;
}

function sameSubmission(row: JobRow, sub: Submission): boolean {
  return row.input === sub.input && row.steps === sub.steps && row.fail_attempts === sub.failAttempts;
}

/** Creates a job, or replays/conflicts with an earlier submission that used the same key. */
function createJob(sub: Submission, key: string | undefined): { status: 200 | 201 | 409; job?: Job } {
  if (key === undefined) return { status: 201, job: toJob(insertJob(sub, null)) };
  return inTransaction(db, () => {
    const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as unknown as JobRow | undefined;
    if (existing) {
      return sameSubmission(existing, sub) ? { status: 200 as const, job: toJob(existing) } : { status: 409 as const };
    }
    return { status: 201 as const, job: toJob(insertJob(sub, key)) };
  });
}

async function handleCreateJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  const fields: FieldError[] = [];

  let body: unknown;
  if (!isJsonContentType(req.headers['content-type'])) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (tooLarge) {
    fields.push({ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` });
  } else {
    try {
      body = JSON.parse(text);
    } catch {
      fields.push({ field: 'body', message: 'body must be valid JSON' });
    }
  }

  let submission: Submission | undefined;
  if (fields.length === 0) {
    const result = validateSubmission(body);
    if (result.ok) submission = result.value;
    else fields.push(...result.fields);
  }

  const key = req.headers['idempotency-key'];
  if (key !== undefined && !IDEMPOTENCY_KEY_PATTERN.test(key)) {
    fields.push({ field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  if (fields.length > 0 || !submission) return invalidRequest(res, fields);

  const outcome = createJob(submission, key);
  if (outcome.status === 409) {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was used with a different payload.');
  }
  send(res, outcome.status, outcome.job);
}

function handleHealth(res: ServerResponse): void {
  const hb = db.prepare("SELECT at FROM heartbeats WHERE name = 'worker'").get() as { at: number } | undefined;
  const up = hb !== undefined && Date.now() - Number(hb.at) <= WORKER_STALE_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';
  const notAllowed = () => sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed here.`);

  if (pathname === '/health') {
    return method === 'GET' ? handleHealth(res) : notAllowed();
  }
  if (pathname === '/') {
    if (method !== 'GET') return notAllowed();
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') {
      const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
      return send(res, 200, { jobs: rows.map(toJob) });
    }
    if (method === 'POST') return handleCreateJob(req, res);
    return notAllowed();
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return notAllowed();
    const row = getJobRow(decodeURIComponent(match[1]!));
    if (!row) return sendError(res, 404, 'not_found', 'No job with that id.');
    return send(res, 200, toJob(row));
  }
  sendError(res, 404, 'not_found', `No route for ${pathname}.`);
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal error.');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), 1000).unref();
  setTimeout(() => process.exit(0), 3000).unref();
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

