import { setInterval as every, setTimeout as sleep } from 'node:timers/promises';
import { clearInterval } from 'node:timers';
import { inTransaction, openDatabase } from './db.ts';
import { MAX_ATTEMPTS, RETRY_DELAY_MS, STEP_MS, TRANSIENT_ERROR, nowIso, type JobRow } from './jobs.ts';

const HEARTBEAT_MS = 1000;
const IDLE_POLL_MS = 200;

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

function heartbeat(): void {
  db.prepare(
    "INSERT INTO heartbeats (name, at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at",
  ).run(Date.now());
}

/** Attempts that were running when a previous worker died are abandoned and will be processed again. */
function requeueRunning(): void {
  db.prepare("UPDATE jobs SET status = 'queued', completed = 0, updated_at = ? WHERE status = 'running'").run(nowIso());
}

/** Claims the oldest due queued job and starts a new attempt on it. */
function claimNext(): JobRow | undefined {
  return inTransaction(db, () => {
    const next = db
      .prepare("SELECT seq FROM jobs WHERE status = 'queued' AND next_run_at <= ? ORDER BY seq LIMIT 1")
      .get(Date.now()) as { seq: number } | undefined;
    if (!next) return undefined;
    db.prepare("UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ? WHERE seq = ?").run(
      nowIso(),
      next.seq,
    );
    return db.prepare('SELECT * FROM jobs WHERE seq = ?').get(next.seq) as unknown as JobRow;
  });
}

function requeue(id: string, nextRunAt: number): void {
  db.prepare("UPDATE jobs SET status = 'queued', completed = 0, next_run_at = ?, updated_at = ? WHERE id = ?").run(
    nextRunAt,
    nowIso(),
    id,
  );
}

function setProgress(id: string, completed: number): void {
  db.prepare('UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ?').run(completed, nowIso(), id);
}

function finish(job: JobRow): void {
  db.prepare("UPDATE jobs SET status = 'completed', completed = steps, output = ?, error = NULL, updated_at = ? WHERE id = ?").run(
    job.input.toUpperCase(),
    nowIso(),
    job.id,
  );
}

function fail(id: string): void {
  db.prepare("UPDATE jobs SET status = 'failed', completed = 0, output = NULL, error = ?, updated_at = ? WHERE id = ?").run(
    TRANSIENT_ERROR,
    nowIso(),
    id,
  );
}

/** Runs one attempt. `job.attempts` already includes this attempt. */
async function runAttempt(job: JobRow): Promise<void> {
  if (job.attempts <= job.fail_attempts) {
    // Simulated transient failure at the first step, before any progress.
    if (job.attempts >= MAX_ATTEMPTS) fail(job.id);
    else requeue(job.id, Date.now() + RETRY_DELAY_MS);
    return;
  }
  for (let step = 1; step <= job.steps; step++) {
    if (stopping) {
      // Shutting down mid-attempt: hand the job back so the next worker starts it again.
      requeue(job.id, 0);
      return;
    }
    await sleep(STEP_MS);
    setProgress(job.id, step);
  }
  finish(job);
}

requeueRunning();
heartbeat();
const heartbeatTimer = setInterval(() => {
  try {
    heartbeat();
  } catch (e) {
    console.error('heartbeat failed:', e);
  }
}, HEARTBEAT_MS);

console.log('worker started');
while (!stopping) {
  let job: JobRow | undefined;
  try {
    job = claimNext();
  } catch (e) {
    console.error('claim failed:', e);
  }
  if (!job) {
    await sleep(IDLE_POLL_MS);
    continue;
  }
  try {
    await runAttempt(job);
  } catch (e) {
    console.error(`attempt on job ${job.id} failed:`, e);
    await sleep(IDLE_POLL_MS);
  }
}

clearInterval(heartbeatTimer);
db.prepare("DELETE FROM heartbeats WHERE name = 'worker'").run();
requeueRunning();
db.close();
console.log('worker stopped');

